from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_seps = {r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background}
    col_seps = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background}

    def segments(size, separators):
        parts, start = [], 0
        for i in range(size):
            if i in separators:
                if start < i:
                    parts.append(list(range(start, i)))
                start = i + 1
        if start < size:
            parts.append(list(range(start, size)))
        return parts

    row_panels = segments(h, row_seps)
    col_panels = segments(w, col_seps)
    panels = [(rs, cs) for rs in row_panels for cs in col_panels]

    def content(rs, cs):
        return [(i, j, grid[rs[i]][cs[j]])
                for i in range(len(rs)) for j in range(len(cs))
                if grid[rs[i]][cs[j]] != background]

    source = max(panels, key=lambda panel: len(content(*panel)))
    motif = content(*source)
    out = [row[:] for row in grid]
    for rs, cs in panels:
        if (rs, cs) == source or (len(rs), len(cs)) != (len(source[0]), len(source[1])):
            continue
        for i, j, color in motif:
            out[rs[i]][cs[j]] = color
    return out

